window.ScripturaLexicons.BDAG_PART_0235 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-01\" data-source=\"BDAG\" data-search=\"μηθέν forma remissiva ver μηδείς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηθέν</td><td>forma remissiva</td><td>ver μηδείς</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-02\" data-source=\"BDAG\" data-search=\"μηκέτι advérbio não mais; doravante não BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηκέτι</td><td>advérbio</td><td>não mais; doravante não</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-03\" data-source=\"BDAG\" data-search=\"μῆκος, ους, τό substantivo neutro comprimento; extensão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μῆκος, ους, τό</td><td>substantivo neutro</td><td>comprimento; extensão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-04\" data-source=\"BDAG\" data-search=\"μηκύνω verbo alongar; crescer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηκύνω</td><td>verbo</td><td>alongar; crescer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-05\" data-source=\"BDAG\" data-search=\"μηλωτή, ῆς, ἡ substantivo feminino pele de ovelha usada como capa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηλωτή, ῆς, ἡ</td><td>substantivo feminino</td><td>pele de ovelha usada como capa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-06\" data-source=\"BDAG\" data-search=\"μήν partícula enfática com efeito; contudo; nem sequer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήν</td><td>partícula enfática</td><td>com efeito; contudo; nem sequer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-07\" data-source=\"BDAG\" data-search=\"μήν, μηνός, ὁ substantivo masculino mês; lua nova BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήν, μηνός, ὁ</td><td>substantivo masculino</td><td>mês; lua nova</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-08\" data-source=\"BDAG\" data-search=\"μηνιάω verbo enfurecer-se; sentir ira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηνιάω</td><td>verbo</td><td>enfurecer-se; sentir ira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-09\" data-source=\"BDAG\" data-search=\"μῆνις, ιος substantivo feminino ira implacável; vingança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μῆνις, ιος</td><td>substantivo feminino</td><td>ira implacável; vingança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-10\" data-source=\"BDAG\" data-search=\"μηνύω verbo informar; revelar; denunciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηνύω</td><td>verbo</td><td>informar; revelar; denunciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-11\" data-source=\"BDAG\" data-search=\"μὴ οὐ expressão remissiva ver μή 4 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μὴ οὐ</td><td>expressão remissiva</td><td>ver μή 4</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-12\" data-source=\"BDAG\" data-search=\"μήποτε advérbio e conjunção nunca; receando que; talvez BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήποτε</td><td>advérbio e conjunção</td><td>nunca; receando que; talvez</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-13\" data-source=\"BDAG\" data-search=\"μήπου advérbio remissivo ver πού BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήπου</td><td>advérbio remissivo</td><td>ver πού</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-14\" data-source=\"BDAG\" data-search=\"μήπω advérbio ainda não BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήπω</td><td>advérbio</td><td>ainda não</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-15\" data-source=\"BDAG\" data-search=\"μήπως advérbio remissivo ver πώς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήπως</td><td>advérbio remissivo</td><td>ver πώς</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-16\" data-source=\"BDAG\" data-search=\"μηρός, οῦ, ὁ substantivo masculino coxa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηρός, οῦ, ὁ</td><td>substantivo masculino</td><td>coxa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-17\" data-source=\"BDAG\" data-search=\"μήτε conjunção negativa nem; nem...nem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήτε</td><td>conjunção negativa</td><td>nem; nem...nem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-18\" data-source=\"BDAG\" data-search=\"μήτηρ, τρός, ἡ substantivo feminino mãe; origem; fonte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήτηρ, τρός, ἡ</td><td>substantivo feminino</td><td>mãe; origem; fonte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-19\" data-source=\"BDAG\" data-search=\"μήτι partícula interrogativa pergunta com resposta negativa esperada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήτι</td><td>partícula interrogativa</td><td>pergunta com resposta negativa esperada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0235-20\" data-source=\"BDAG\" data-search=\"μήτιγε partícula remissiva ver μήτι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήτιγε</td><td>partícula remissiva</td><td>ver μήτι</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0235-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηθέν</h1><div class=\"entry-meta\"><span>forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηθέν</span>, ver <span class=\"greek\">μηδείς</span>, início.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηκέτι</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηκέτι</span>, advérbio (Hom.+; inscrições, papiros, LXX, En, TestSol, TestJob; TestReub; Joseph., Just., Tat.), não mais, doravante não, nos mesmos usos que <span class=\"greek\">μή</span>.</p><p class=\"entry-text\">ⓐ Em orações finais; depois de <span class=\"greek\">ἵνα</span> (Just., A II, 7, 1; POxy 528, 23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:14</a>; AcPl Ha 2, 32.</p><p class=\"entry-text\">ⓑ Em orações consecutivas; depois de <span class=\"greek\">ὥστε</span> (2 Macc 4:14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:45</a>; 2:2. Com infinitivo de consequência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:2</a>.</p><p class=\"entry-text\">ⓒ Com particípio (Tob 5:10 S; Jos., Ant. 13, 399; TestReub 3:15; Just., D. 24, 3; 45, 4; Tat. 9:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:1</a>, 5; 15:7; IMg 9:1; Hv 3, 11, 3; AcPl Ha 5, 14.</p><p class=\"entry-text\">ⓓ Com infinitivo (Josh 22:33; 2 Ch 16:5; 2 Macc 10:4; En 103:10; Demetr.: 722 Fgm. 1, 9 Jac.; Jos., Ant. 8, 45; 47; Just., D. 6, 2 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:17</a>; 25:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:17</a>; Hm 4, 1, 11; 4, 3, 2; Hs 9, 9, 6.</p><p class=\"entry-text\">ⓔ Em oração relativa MPol 2:3; Hs 8, 11, 3.</p><p class=\"entry-text\">ⓕ Em oração independente.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com imperativo (Ex 36:6; 1 Macc 13:39) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:14</a>; 8:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:23</a>; Hv 3, 3, 2; 16, 9; 61, 4.—Em vez deste, ocorre o subjuntivo aoristo (Tob 14:9 BA) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:25</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">καρπὸς</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span>, nunca mais nascerá fruto de ti <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:19</a>; Hv 2, 3, 1. Com acumulação de negações (cf. <span class=\"greek\">β</span> e <span class=\"greek\">γ</span> abaixo), <span class=\"greek\">οὐ</span> <span class=\"greek\">μηκέτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:19</a>, variante de leitura. <span class=\"greek\">μηκέτι</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">αἰτήσεις</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἀποκαλύψεως</span>, não me faças mais perguntas sobre a revelação Hv 3, 13, 4.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com optativo, em dupla negação: <span class=\"greek\">μ</span>. … <span class=\"greek\">μηδεὶς</span> <span class=\"greek\">καρπὸν</span> <span class=\"greek\">φάγοι</span>, nunca mais alguém coma fruto de ti <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:14</a> (cf. <span class=\"greek\">μηδείς</span> 2a).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Com subjuntivo exortativo (Sir 21:1 <span class=\"greek\">μὴ</span> <span class=\"greek\">προσθῇς</span> <span class=\"greek\">μηκέτι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:13</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῆκος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μῆκος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. e outros; inscrições, papiros, LXX, TestSol; EpArist, GrBar 2:5; EpArist, Philo; Jos., Bell. 4, 467; 482, Ant. 12, 231; SibOr 3, 649), comprimento; em nossa literatura, apenas espacialmente: com largura, altura, profundidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:18</a> (cf. <span class=\"greek\">βάθος</span> 1). Com largura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:16a</a>, e com largura e altura (Diod S 13, 82, 2 <span class=\"greek\">μῆκος</span>, <span class=\"greek\">πλάτος</span> <span class=\"greek\">ὕψος</span> acerca do templo de Zeus em Acragas, com medidas exatas; 16, 83, 2) versículo 16b. <span class=\"greek\">τῷ</span> <span class=\"greek\">μήκει</span>, em comprimento = comprido, com a medida indicada Hv 4, 1, 6 (Da 4:12 <span class=\"greek\">οἱ</span> <span class=\"greek\">κλάδοι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μήκει</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">σταδίων</span> <span class=\"greek\">τριάκοντα</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηκύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηκύνω</span> (Pind., Hdt. e outros; PLond V 1708, 131; LXX; EpArist 8), tornar comprido (“fazer crescer” Is 44:14); na voz média, tornar-se comprido, crescer (em comprimento) (Philo, Agr. 17, figuradamente sobre árvores; Jos., Ant. 12, 357); do grão que brota <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:27</a>.—DELG s.v. <span class=\"greek\">μακρός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηλωτή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηλωτή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Philemon Com. [IV/III a.C.] 25; Pamphilus [I a.C./I d.C.] em Ael. Dion. <span class=\"greek\">ω</span>, 1; cf. <span class=\"greek\">ο</span>, 5; Apollon. Dysc., Synt. 191, 9; OGI 629, 32; PTebt 38, 22 [II a.C.]; PMich 421, 24 [I d.C.]; LXX), pele de ovelha usada como capa pelos profetas (3 Km 19:13, 19; 4 Km 2:8, 13f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:37</a>; 1 Cl 17:1.—DELG s.v. 2 <span class=\"greek\">μῆλον</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήν</h1><div class=\"entry-meta\"><span>partícula enfática</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήν</span>, partícula (Hom.+; UPZ 59, 27 [168 a.C.]; LXX; JosAs 1:9 cód. A [p. 40, 11 Bat.] <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴν</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span>; ApcSed 14, 10 p. 136, 18 Tdf. <span class=\"greek\">ἦ</span> <span class=\"greek\">μήν</span>; Philo, Joseph., Just., Ath.—Denniston 325–58), usada com outras partículas para dar ênfase.</p><p class=\"entry-text\">① <span class=\"greek\">εἰ</span> <span class=\"greek\">μήν</span>, ver esse verbete.</p><p class=\"entry-text\">② <span class=\"greek\">καὶ</span> <span class=\"greek\">μήν</span> (Hom., Pind. e outros; BGU 1024, 7; 24; Jos., C. Ap. 2, 257, Vi. 256), e de fato.</p><p class=\"entry-text\">ⓐ Em contraste com o que precede, e contudo (Just., D. 35, 1; Ath. 8, 4; Kühner-G. II 137; B-D-F §450, 4) 9:6.</p><p class=\"entry-text\">ⓑ Com efeito, de fato Hm 4, 1, 8; 5, 1, 7. <span class=\"greek\">οὐ</span> <span class=\"greek\">μήν</span>, certamente ... não, naturalmente ... não Dg 5:3 (Diod S 2, 18, 8; EpArist 158; Jos. Ant. 15, 42; Ath. 23, 1).</p><p class=\"entry-text\">③ <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">μήν</span>, por outro lado (Jos., Ant. 19, 146; C. Ap. 1, 286; 2, 289; Just. D. 5, 3) Dg 4:1.</p><p class=\"entry-text\">④ <span class=\"greek\">μήτε</span> <span class=\"greek\">μήν</span>, nem sequer Ox 840, 15.—DELG 1 <span class=\"greek\">μήν</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήν, μηνός, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήν</span>, <span class=\"greek\">μηνός</span>, <span class=\"greek\">ὁ</span> (Hom.+).</p><p class=\"entry-text\">① Mês <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:36</a>; PtK 2 p. 14, 27. Acusativo de tempo que responde à pergunta: por quanto tempo? (B-D-F §161, 2; Rob. 469f), por cinco meses <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:24</a>; cf. versículo 56; 4:25, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:20</a>; 18:11; 20:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:5</a>, 10; 11:2; 13:5. <span class=\"greek\">τρεῖς</span> <span class=\"greek\">μῆνας</span> GJs 12:3. Com preposição: <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. (com hora, dia, ano) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:15</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:26</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">μῆνας</span> <span class=\"greek\">τρεῖς</span>, por um período de três meses (ver Jos., Bell. 2, 180) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:8</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">μῆνα</span> <span class=\"greek\">ἕκαστον</span>, todos os meses <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:2</a> (PRev 16, 2 [258 a.C.] <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕκαστον</span> <span class=\"greek\">μῆνα</span>; X., Oec. 9, 8 <span class=\"greek\">κατὰ</span> <span class=\"greek\">μῆνα</span>). <span class=\"greek\">μετὰ</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">μῆνας</span>, depois de três meses <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:11</a>. De uma mulher que dá à luz GJs 5:2; 7:1; 13:1. Em data exata: <span class=\"greek\">μηνὸς</span> <span class=\"greek\">Ξανθικοῦ</span> <span class=\"greek\">δευτέρᾳ</span> <span class=\"greek\">ἱσταμένου</span> = 22 de fevereiro, MPol 21; sobre isso, ver <span class=\"greek\">ἵστημι</span>, final, e ESchwartz, Christl. u. jüd. Ostertafeln: AGG n.s. 8, 1905, 127ff.</p><p class=\"entry-text\">② Lua nova (festa) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:10</a>; Dg 4:5.—B. 1010. Heath, Aristarchus 284–87. DELG 2 <span class=\"greek\">μήν</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηνιάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηνιάω</span> (<span class=\"greek\">μῆνις</span>), forma do grego helenístico em lugar do mais antigo <span class=\"greek\">μηνίω</span> (Apollon. Rhod. 2, 247; Dionys. Hal., Rhet. 9, 16; Aelian, NA 6, 17; Chariton 1, 2; Sir 10:6; Philo, Abr. 213; Jos., Ant. 8, 112, variante de leitura.—Phryn. p. 82 Lob.); subjuntivo aoristo, 2ª pessoa singular, <span class=\"greek\">μηνιάσῃς</span> (Sir 10:6), alimentar ira, enfurecer-se <span class=\"greek\">τινί</span>, contra alguém: <span class=\"greek\">ἀλλήλοις</span> Hs 9, 23, 3.—DELG s.v. <span class=\"greek\">μῆνις</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῆνις, ιος</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μῆνις</span>, <span class=\"greek\">ιος</span> (forma jônica do genitivo; cf. a reminiscência homérica em Pla., Rep. 390e e <span class=\"greek\">δήριος</span> Aeschyl, Ag. 942: EFraenkel, Aeschylus Agamemnon II, ’62 [’50], 427) e, posteriormente, <span class=\"greek\">ιδος</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; PRyl 67, 3 [II a.C.]; BGU 1026, 22, 14; LXX; Jos., Ant. 9, 104; TestDan 5:2; SibOr 4, 135), ira implacável, sentimento de vingança, com <span class=\"greek\">ὀργή</span> descrita como fonte de <span class=\"greek\">μ</span>. Hm 5, 2, 4 (sobre a relação entre <span class=\"greek\">ὀργή</span> e <span class=\"greek\">μῆνις</span> no estoicismo, ver Diog. L. 7, 113. Andronicus, <span class=\"greek\">περὶ</span> <span class=\"greek\">παθῶν</span> 4 [Stoic. III n.º 397]; Ps.-Phoc. 64; Sir 27:30). Descrita no mesmo lugar como pecado incurável.—DELG. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηνύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηνύω</span>, 1º aoristo <span class=\"greek\">ἐμήνυσα</span>; perfeito <span class=\"greek\">μεμήνυκα</span>; 1º aoristo passivo <span class=\"greek\">ἐμηνύθη</span> 2 Macc 14:37; particípio <span class=\"greek\">μηνυθείς</span> (Pind., Hdt.+), oferecer informação considerada de especial interesse, informar, dar a conhecer, revelar: <span class=\"greek\">μηνύοντες</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀδελφοῖς</span>, informando os irmãos e as irmãs a seu respeito (isto é, sobre a chegada de Paulo) AcPl Ha 8, 5; precedido de oração afirmativa (<span class=\"greek\">ὅτι</span>; cf. Jos., Ant. 1, 198) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:37</a> (sobre a Escritura, como em Philo, Op. M. 15; 77; Just., D. 56, 1). Objeto facilmente suprido pelo contexto: <span class=\"greek\">ὁ</span> <span class=\"greek\">μηνύσας</span> (Demetr.: 722 Fgm. 2, 1 Jac.), quem vos informou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:28</a>. Comunicar por escrito MPol 20:1 (Ath. 1, 3). Especialmente também no sentido forense, denunciar, prestar informações às autoridades (Appian, Bell. Civ. 4, 7 §30; UPZ 121, 15; 25 [156 a.C.]; PLond III, 1171 verso c, 7 p. 107 [42 d.C.]; PGiss 61, 7 e outros; Jos., Ant. 4, 220; sobre o papel do <span class=\"hebrew\" dir=\"rtl\">מָסוֹר</span>, “informante”, na sociedade israelita, ver WKlassen, Judas ’96, 62–66) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.57\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:57</a>. Passivo: <span class=\"greek\">μηνυθείσης</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐπιβουλῆς</span>, depois que me foi revelado que havia uma conspiração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:30</a> (o dativo como em Diod S 2, 28, 4 <span class=\"greek\">μηνυθείσης</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πράξεως</span> = depois que o fato lhe foi comunicado; APF 8 p. 214, 9 [79 a.C.] <span class=\"greek\">τοῖς</span> <span class=\"greek\">στρατηγοῖς</span>).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μὴ οὐ</h1><div class=\"entry-meta\"><span>expressão remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μὴ</span> <span class=\"greek\">οὐ</span>, ver <span class=\"greek\">μή</span> 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήποτε</h1><div class=\"entry-meta\"><span>advérbio e conjunção</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήποτε</span> (Hom.+. Sobre sua separação como <span class=\"greek\">μή</span> <span class=\"greek\">ποτε</span>, ver KLipsius, Gramm. Unters. über die bibl. Gräzität 1863, 129f).</p><p class=\"entry-text\">① Indicador de um ponto temporal negado indefinido, nunca, com indicativo (frequentemente no grego helenístico) <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">μήποτε</span> <span class=\"greek\">ἰσχύει</span>, uma vez que nunca tem validade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:17</a> (variante de leitura <span class=\"greek\">μὴ</span> <span class=\"greek\">τότε</span>; ver B-D-F §428, 5).</p><p class=\"entry-text\">② Indicador de finalidade negada, para que ... não, conjunção frequentemente empregada como forma enfática de <span class=\"greek\">μή</span>.</p><p class=\"entry-text\">ⓐ Depois de verbos de temer, preocupar-se etc., que ... não, receando que, para que não (Diod S 11, 20, 2 e ApcMos 16:18, 21 <span class=\"greek\">φοβεῖσθαι</span> <span class=\"greek\">μήποτε</span>).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com subjuntivo aoristo: <span class=\"greek\">προσέχετε</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">βαρηθῶσιν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">καρδίαι</span> <span class=\"greek\">ὑμῶν</span>, cuidai para que ... não ... <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:34</a> (cf. Sir 11:33). <span class=\"greek\">βλέπε</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀναβῇ</span> Hs 5, 7, 2.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com subjuntivo presente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:1</a> (JosAs 12:10 <span class=\"greek\">μ</span>. <span class=\"greek\">ἁρπάζῃ</span> <span class=\"greek\">με</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">λύκος</span>).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Com futuro do indicativo (En 106:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:12</a>.</p><p class=\"entry-text\">ⓑ Denotando finalidade, (a fim de) que ... não, frequentemente exprimindo apreensão:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com subjuntivo aoristo (Diod S 15, 20, 1; Gen 38:23; 2 Esdr 4:22; SSol 1:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:6</a> (Ps 90:12); 5:25; 13:15 (Is 6:10), 29; 15:32; 27:64; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:12</a> (Is 6:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:11</a> (Ps 90:12); 14:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:39</a>; 16:39 D; 20:16 D; 28:27 (Is 6:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:1</a>; Hm 10, 2, 5; Hs 9, 28, 7; AcPl Ha 1, 21. Depois de <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:29</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com subjuntivo presente 12:58; 14:8.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Com futuro do indicativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:2</a>; mas a leitura varia nas duas passagens; 19:7.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. Em dupla negação: <span class=\"greek\">μήποτε</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβηθήσονται</span>, para que não deixem de temer D 4:10.</p><p class=\"entry-text\">③ Indicador de pergunta, se porventura.</p><p class=\"entry-text\">ⓐ Em pergunta direta (Judg 3:24; Tob 10:2; EpArist 15) <span class=\"greek\">μήποτε</span> <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">ἔγνωσαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄρχοντες</span>; será que as autoridades realmente vieram a saber? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:26</a>.</p><p class=\"entry-text\">ⓑ Em pergunta indireta.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com optativo (Jos., Bell. 1, 609) <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">εἴη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστός</span>, se porventura ele próprio seria o Messias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:15</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com subjuntivo <span class=\"greek\">μ</span>. <span class=\"greek\">δώῃ</span> (ver <span class=\"greek\">δίδωμι</span>, início) <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">μετάνοιαν</span>, (para verificar) se Deus porventura lhes concederá arrependimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:25</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Com indicativo aoristo, quando o conteúdo da pergunta se refere ao passado (Arrian, Anab. 7, 24, 3 “se porventura”, com pergunta indireta referente ao passado) GPt 5:15 (ver também <span class=\"greek\">ἀγωνιάω</span>).</p><p class=\"entry-text\">④ Por vezes a negação é tão enfraquecida que <span class=\"greek\">μήποτε</span> introduz algo conjecturado: provavelmente, talvez (Aristot., EN 10, 1; 10; M. Ant. 4, 24; Job 1:5; Sir 19:13f; Philo, Sacr. Abel. 72, Det. Pot. Ins. 168). <span class=\"greek\">μήποτε</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀρκέσῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:9</a>, variante de leitura: talvez não haja suficiente (ver PJoüon, RSR 15, 1925, 438; Mayser II/2, p. 548). O tom é mais enérgico na redação do texto <span class=\"greek\">μήποτε</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀρκέσῃ</span>, certamente nunca haveria o suficiente.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήπου</h1><div class=\"entry-meta\"><span>advérbio remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήπου</span>, ver <span class=\"greek\">πού</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήπω</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήπω</span>, advérbio (Hom. e outros; POxy 1062, 15; Just., A I, 19, 3; Ath. 17, 2), ainda não; com acusativo e infinitivo: <span class=\"greek\">μ</span>. <span class=\"greek\">πεφανερῶσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> <span class=\"greek\">ὁδόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:8</a>. Com particípio (Pla., Symp. 187d; Sb 5343, 37 [182 d.C.]; Jos., Ant. 1, 217): <span class=\"greek\">μ</span>. <span class=\"greek\">γεννηθέντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:11</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">φυγών</span> 2 Cl 18:2.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήπως</h1><div class=\"entry-meta\"><span>advérbio remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήπως</span>, ver <span class=\"greek\">πώς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηρός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηρός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom. e outros; papiros [de um camelo marcado na coxa: PLond III, 1132b, 5 p. 142 [142 d.C.]. De modo semelhante, Ps.-Callisth. 1, 15, 2, acerca de Bucéfalo: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μηρῷ</span> <span class=\"greek\">αὐτοῦ</span>]; LXX; TestSol 1:12 D; TestNapht 1:6, 7; JosAs, ParJer; Jos., Ant. 1, 243), coxa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:16</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήτε</h1><div class=\"entry-meta\"><span>conjunção negativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήτε</span> (Hom. e outros; papiros, LXX, En, EpArist, Joseph., Just., Tat., Ath.), conjunção copulativa negativa (B-D-F §445; Rob. 1189): e não, na tradição manuscrita nem sempre cuidadosamente distinguida de <span class=\"greek\">μηδέ</span> (B-D-F §445, 1; Rob. 1189); continua <span class=\"greek\">μή</span>: não ... e não, nem ... nem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:33</a> (variantes de leitura <span class=\"greek\">μή</span> … <span class=\"greek\">μηδέ</span> e <span class=\"greek\">μήτε</span> … <span class=\"greek\">μήτε</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:20</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:27</a>, variante de leitura. Mais de um <span class=\"greek\">μ</span>. depois de <span class=\"greek\">μή</span>: nem ... nem ... nem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:1</a>, 3. <span class=\"greek\">μήτε</span> … <span class=\"greek\">μήτε</span>, nem ... nem (Jos., Bell. 5, 533, Ant. 15, 168; Just., D. 1, 5; 7, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:12</a>, 21; 27:20 (continuado por <span class=\"greek\">τέ</span> como em X., An. 4, 4, 6); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:3</a>; B 16:10; 19:11; D 4:13; Pol 7:1; MPol 2:2. <span class=\"greek\">καὶ</span> <span class=\"greek\">μ</span>. … <span class=\"greek\">μ</span>., e nem ... nem ISm 7:2.—Um elemento precedente negado é dividido em suas partes por mais de um <span class=\"greek\">μήτε</span> subsequente: <span class=\"greek\">μὴ</span> <span class=\"greek\">ὀμόσαι</span> <span class=\"greek\">ὅλως</span>, <span class=\"greek\">μήτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῷ</span> … , <span class=\"greek\">μήτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γῇ</span> … , <span class=\"greek\">μήτε</span> …, não ... nem ... nem ... nem Mt 5:34ff. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>. <span class=\"greek\">μηδὲν</span> … <span class=\"greek\">μήτε</span> … <span class=\"greek\">μήτε</span>, nada ... nem ... nem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:3</a>. <span class=\"greek\">μὴ</span> … <span class=\"greek\">μηδὲ</span> … , <span class=\"greek\">μήτε</span> … <span class=\"greek\">μήτε</span> … <span class=\"greek\">μήτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a> (os dois primeiros membros são equivalentes; o segundo é dividido então em três partes. Sobre a acumulação de negações, cf. Phalaris, Ep. 91 <span class=\"greek\">μήτε</span> … <span class=\"greek\">μήτε</span> … <span class=\"greek\">μηδεὶς</span> … <span class=\"greek\">μηδὲν</span> … <span class=\"greek\">μηδ</span>’; Aelian, VH 14, 22 <span class=\"greek\">μηδένα</span> <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">διαλέγεσθαι</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">κοινῇ</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">ἰδίᾳ</span>; Synes., Dreams 19 p. 153c <span class=\"greek\">τὰ</span> <span class=\"greek\">μηδαμῆ</span> <span class=\"greek\">μηδαμῶς</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">ὄντα</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">ἔχοντα</span>; IG IV2/1, 68, 60–65 [302 a.C.] <span class=\"greek\">μή</span> … <span class=\"greek\">μήτε</span> … <span class=\"greek\">μηδέ</span>; Tat. 17, 4 <span class=\"greek\">μηδέν</span> … <span class=\"greek\">μήτε</span> … <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">μηδέ</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήτηρ, τρός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήτηρ</span>, <span class=\"greek\">τρός</span>, <span class=\"greek\">ἡ</span> (“mãe”; Hom.+).</p><p class=\"entry-text\">① Progenitora do sexo feminino, mãe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18</a>; 13:55; 14:8, 11; 20:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:24</a>, 28 e frequentemente; ApcPt Ox 849, 7. Com o filho dela (cf. EpArist 27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:11</a>, 13f, 20f. Com o pai 10:37; 15:4a (Ex 20:12). Cf. versículo 4b (Hes., Works 331–34 também sabe que quem maltrata ou fala rudemente com o pai idoso é punido por Zeus); 19:5 (Gen 2:24), 19 (Ex 20:12), 29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:40</a> e outros. Com irmãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:46</a>; Mk 3:31–33. Com avó <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:5</a> (ver <span class=\"greek\">μάμμη</span>).—GHb 20, 61 apresenta a ideia extraordinária de que o Espírito Santo (<span class=\"hebrew\" dir=\"rtl\">רוּחָא</span> <span class=\"hebrew\" dir=\"rtl\">דְּקֻדְּשָׁא</span>, gênero feminino) era a mãe de Cristo; ver <span class=\"greek\">πνεῦμα</span> 5c<span class=\"greek\">α</span>, final.</p><p class=\"entry-text\">② Entidade que mantém uma relação semelhante à de uma mãe, mãe, transferência de sentido da acepção 1.</p><p class=\"entry-text\">ⓐ De pessoa respeitada ou amada como mãe (Diod S 17, 37, 6 <span class=\"greek\">ὦ</span> <span class=\"greek\">μῆτερ</span>, dirigido a senhora idosa muito estimada; POxy 1296, 8; 15; 1678; PGiss 78, 1) Mt 12:49f; Mk 3:34f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:27</a> (Duris [III a.C.]: 76 Fgm. 63 Jac.: Polycrates apresenta a cidadãos ricos as mães dos mortos em combate com as palavras <span class=\"greek\">μητέρα</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">δίδωμι</span>; Lucian, Tox. 22); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:13</a>.</p><p class=\"entry-text\">ⓑ De entidades impessoais.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. De cidades (como <span class=\"hebrew\" dir=\"rtl\">אֵם</span>) em relação aos cidadãos; assim, arquetipicamente, de Jerusalém celestial, isto é, da comunidade messiânica em relação a seus membros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:26</a>; cf. versículo 22.—JPlumpe, Mater Ecclesia: An Inquiry into the Concept of Church as Mother in Early Christianity, ’43.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. De um estado ou qualidade considerado ponto de origem ou fonte (Theognis 1, 385; Hippocr. em Synes., Ep. 115 p. 255b <span class=\"greek\">τ</span>. <span class=\"greek\">ἐνδείαν</span> <span class=\"greek\">ὑγιείας</span> <span class=\"greek\">μητέρα</span>; X., Oec. 5, 17 <span class=\"greek\">τ</span>. <span class=\"greek\">γεωργίαν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἄλλων</span> <span class=\"greek\">τεχνῶν</span> <span class=\"greek\">μητέρα</span> <span class=\"greek\">εἶναι</span>; Tob 4:13; JosAs 15:7 [sobre <span class=\"greek\">μετάνοια</span>]; Ps.-Phoc. 42 <span class=\"greek\">μ</span>. <span class=\"greek\">κακότητος</span>; Philo; TestSim 5:3), da fé, como fonte de virtudes cristãs (Hierocles 11, 442 <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐσέβεια</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀρετῶν</span>) Hv 3, 8, 5; cf. 7. Babilônia, <span class=\"greek\">ἡ</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πορνῶν</span> <span class=\"greek\">κτλ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:5</a>.—B. 103. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήτι</h1><div class=\"entry-meta\"><span>partícula interrogativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήτι</span>, indicador que solicita resposta negativa à pergunta que introduz. É um pouco mais enfático que <span class=\"greek\">μή</span> simples (Aeschyl., Prom. 959; Epict. 2, 11, 20; 4, 1, 133; Mal 3:8, variante de leitura; Just., D. 68, 3f.—B-D-F §427, 2; 440; Rob. 1172; 1176). Diversos recursos (inclusive advérbios, verbos auxiliares e acentuação) podem traduzir a força dessa partícula; por exemplo: <span class=\"greek\">μήτι</span> <span class=\"greek\">συλλέγουσιν</span> <span class=\"greek\">κτλ</span>., certamente eles não recolhem ..., recolhem? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:16</a>; cf. 26:22, 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:21</a>; 14:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:22</a>; 18:35 (em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:5</a>, a melhor leitura não é <span class=\"greek\">μήτι</span>, mas <span class=\"greek\">μή</span> <span class=\"greek\">τι</span> <span class=\"greek\">προσφάγιον</span> <span class=\"greek\">ἔχετε</span>; provavelmente não tendes peixe, tendes?); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:11</a>; Hv 3, 10, 8; Hs 9, 12, 5.—Também em perguntas nas quais quem pergunta tem dúvida acerca da resposta: porventura, talvez (Ps.-Callisth. 2, 14, 9 <span class=\"greek\">μήτι</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀλέξανδρος</span>;) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:29</a> (Schwyzer II 629, nota 2); Hm 4, 4, 1; GJs 13:1.—Com outras partículas: <span class=\"greek\">μ</span>. <span class=\"greek\">ἄρα</span>, então talvez, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:17</a> (TestJob 35:4; B-D-F §440, 2; Rob. 1190). <span class=\"greek\">μήτι</span> <span class=\"greek\">γε</span>, para não falar de, quanto mais (Demosth. 2, 23 <span class=\"greek\">μή</span> <span class=\"greek\">τί</span> <span class=\"greek\">γε</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">θεοῖς</span>; Nicol. Dam.: 90 Fgm. 130, 29 Jac.; Plut., Mor. 14a; PLond I, 42, 23 [<span class=\"greek\">μὴ</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">γε</span>] p. 30 [172 a.C.]; Just., D., 92, 1; Tat. 14, 2; B-D-F §427, 3.—Para introduzir pergunta JosAs 16, 6; Just., D. 92, 1.—Tat. 8, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:3</a>. Depois de <span class=\"greek\">εἰ</span>, ver <span class=\"greek\">εἰ</span> 6j.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0235-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήτιγε</h1><div class=\"entry-meta\"><span>partícula remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήτιγε</span>, ver <span class=\"greek\">μήτι</span>, final.</p></section></article>"};
